package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.utils.Lang;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_clone_TriageGen2Test {

    @Test
    public void testCloneBasicProperties() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("test/path/file.txt");
        original.setInternalAttributes(0x1234);
        original.setExternalAttributes(0x5678L);
        original.setSize(1024L);
        original.setMethod(ZipArchiveEntry.DEFLATED);

        Date date = new Date();
        // Note: getLastModifiedDate/setLastModifiedDate behavior depends on implementation, 
        // but we test the clone mechanism via the provided clone() implementation.

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertNotSame("Clone should be a different object instance", original, cloned);
        Assert.assertEquals("Name should be identical", original.getName(), cloned.getName());
        Assert.assertEquals("Internal attributes should be copied", original.getInternalAttributes(), cloned.getInternalAttributes());
        Assert.assertEquals("External attributes should be copied", original.getExternalAttributes(), cloned.getExternalAttributes());
        Assert.assertEquals("Method should be copied", original.getMethod(), cloned.getMethod());
        Assert.assertEquals("Size should be copied", original.getSize(), cloned.getSize());
    }

    @Test
    public void testCloneWithExtraFields() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("extra_field_test.txt");

        // Using a dummy extra field if possible, or just ensuring the array is handled
        // Since ZipExtraField is abstract/complex, we rely on the method logic coverage
        // We can add a field if we had a concrete implementation, but for coverage 
        // we ensure the call to getExtraFields(true) is exercised.

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertNotSame(original, cloned);
        Assert.assertArrayEquals(original.getExtraFields(), cloned.getExtraFields());
    }

    @Test
    public void testCloneWithDirectory() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("some/directory/");
        // Directories typically have specific attributes, but we test the clone logic

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertEquals(original.getName(), cloned.getName());
        Assert.assertEquals(original.isDirectory(), cloned.isDirectory());
    }

    @Test
    public void testCloneDeepAttributes() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("attr_test.dat");
        original.setUnixMode(0755);
        original.setInternalAttributes(0xAAAA);
        original.setExternalAttributes(0xBBBB);

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertEquals(original.getInternalAttributes(), cloned.getInternalAttributes());
        Assert.assertEquals(original.getExternalAttributes(), cloned.getExternalAttributes());
        // Note: UnixMode might be part of external attributes or a separate field 
        // depending on the specific Apache Commons Compress version implementation
    }

    @Test
    public void testCloneNullName() throws Exception {
        // Testing edge case where name might be empty or specific strings
        ZipArchiveEntry original = new ZipArchiveEntry("");
        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertEquals("", cloned.getName());
    }
}
